def _p(d: dict) -> dict:
    """Drop None values — keeps API calls clean."""
    return {k: v for k, v in d.items() if v is not None}


class DataGoKrClientClient(BaseHttpClient):
    """
    Client for 공공데이터포털 OpenAPI.
    Auth: serviceKey query param, injected automatically.
    Returns normalised dict.
    """

    def _call(
        self,
        url: str,
        params: dict,
    ) -> dict:
        extra = {}
        all_params = {
            "serviceKey": self._api_key or config.API_KEY,
            **extra,
            **params,
        }
        raw = self._raw_get(url, all_params)

        from .base_http_client import _parse_response

        data = _parse_response(raw)
        self._check_result_code(data)

        return data

    def get_power_usage_service(
        self,
        from_date: str,
        to_date: str,
        plant: str,
        clsf_cd: str,
        hogi: str,
        tag: str,
        type: str | None = None,
        page: int = 1,
        page_size: int = 1000,
    ) -> dict:
        """전력사용량 조회 — 발전소명, 호기명, 태그명 및 태그 데이터 생성시간을 기준으로 단위, 태그 값, 센서타입, flag코드를 조회한다."""
        return self._call(
            _GET_POWER_USAGE_SERVICE,
            _p(
                {
                    "fromDate": from_date,
                    "toDate": to_date,
                    "plant": plant,
                    "clsf_cd": clsf_cd,
                    "hogi": hogi,
                    "tag": tag,
                    "type": type,
                    "pageNo": page,
                    "numOfRows": page_size,
                }
            ),
        )

